//! The game window's icon: the Nostyra logo mark, embedded from the launcher's icon
//! set (generated by `tauri icon` from `nostyra-logo-source.svg`, so both apps match).

use winit::window::{Icon, WindowAttributes};

/// Title bar / Alt-Tab size.
const WINDOW_ICON_PNG: &[u8] = include_bytes!("../../launcher/src-tauri/icons/64x64.png");
/// Taskbar size (Windows picks it down to the shell's icon size).
#[cfg(windows)]
const TASKBAR_ICON_PNG: &[u8] = include_bytes!("../../launcher/src-tauri/icons/128x128@2x.png");

/// `attrs` with the logo as window (and on Windows taskbar) icon. A PNG that fails to
/// decode only logs: the window still opens, with the default icon.
pub fn with_logo_icon(attrs: WindowAttributes) -> WindowAttributes {
    let attrs = attrs.with_window_icon(decode_icon(WINDOW_ICON_PNG));
    #[cfg(windows)]
    let attrs = {
        use winit::platform::windows::WindowAttributesExtWindows;
        attrs.with_taskbar_icon(decode_icon(TASKBAR_ICON_PNG))
    };
    attrs
}

fn decode_icon(png: &[u8]) -> Option<Icon> {
    let decoded = image::load_from_memory_with_format(png, image::ImageFormat::Png)
        .map_err(|err| err.to_string())
        .and_then(|image| {
            let rgba = image.into_rgba8();
            let (width, height) = rgba.dimensions();
            Icon::from_rgba(rgba.into_raw(), width, height).map_err(|err| err.to_string())
        });
    match decoded {
        Ok(icon) => Some(icon),
        Err(err) => {
            tracing::warn!(%err, "window icon not set");
            None
        }
    }
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn embedded_logo_pngs_decode() {
        assert!(decode_icon(WINDOW_ICON_PNG).is_some());
        #[cfg(windows)]
        assert!(decode_icon(TASKBAR_ICON_PNG).is_some());
    }
}
